const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(label,route,cls='')=>`<a class="btn ${cls}" href="#${route}">${label}</a>`;
const badge=(label,color='')=>`<span class="badge ${color}">${label}</span>`;
const state={phase:'2',role:'owner',tab:'mine',search:'',kind:'all',status:'all',section:'basics',language:'zh',mode:'edit',width:'desktop',dirty:false,revision:3,submitted:false,previewReady:false,fail:'none',replyDirty:false};
let bridge,route='overview',toastTimer;
let saved={zh:{title:'月影旅馆 · 临港房间',description:'窗边能看见午夜靠港的渡船。书桌上留着一份手绘地图，旅人可以带它去寻找老城里的灯塔。'},en:{title:'Moonshadow Inn · Harbour Room',description:'Watch the midnight ferry from the window. A hand-drawn map on the desk leads to the old lighthouse.'},price:72};
let draft=structuredClone(saved);
const works=[{name:'月影旅馆 · 临港房间',kind:'stay',label:'住宿',persona:'伊莎贝拉',status:'published',state:'已公开 · 有草稿',icon:'⌂',color:'green'}, {name:'旧港口夜行',kind:'experience',label:'活动',persona:'阿莱克斯',status:'rejected',state:'已退回',icon:'◈',color:'orange'}, {name:'旅人装备检修',kind:'service',label:'服务',persona:'伊莎贝拉',status:'draft',state:'草稿',icon:'⚒',color:''}];
const nav=[['overview','概览','◫'],['personas','我的角色','◉'],['works','我的作品','▧'],['interactions','评价与回复','☷'],['admissions','入驻与申请','↗'],['worlds','我管理的世界','◎'],['settings','账号设置','⚙']];
let editorContext='works';
const routeLabels={overview:'我的工作台',personas:'我的角色',persona:'编辑角色',works:'我的作品',editor:'编辑作品',interactions:'评价与回复',admissions:'入驻与申请',worlds:'我管理的世界',world:'拉斯世界管理',review:'审核作品修改',returned:'退回意见','world-new':'创建世界草稿','new-work':'创建作品','admission-review':'审核入驻申请','world-content':'世界内容','world-settings':'世界设定','world-members':'成员与创作者',site:'网站审核',settings:'账号设置'};
function pageNavigation(name){
 const manager=['owner','site'].includes(state.role);
 const worldPath=['overview','worlds','world'];
 let ancestors=['overview'];
 if(route==='overview')ancestors=[];
 else if(route==='persona')ancestors.push('personas');
 else if(['returned','new-work'].includes(route))ancestors.push('works');
 else if(route==='editor')ancestors=editorContext==='world-content'&&manager?[...worldPath,'world-content']:['overview','works'];
 else if(route==='world'&&manager)ancestors.push('worlds');
 else if(['review','admission-review','world-content','world-settings','world-members'].includes(route)&&manager)ancestors=worldPath;
 else if(route==='world-new'&&manager)ancestors.push('worlds');
 const parent=ancestors.at(-1);
 const labels={overview:'返回工作台',works:'返回作品列表',personas:'返回我的角色',worlds:'返回我的世界',world:'返回世界管理','world-content':'返回世界内容'};
 const backLabel=route==='review'?'返回审核队列':labels[parent];
 return `<div class="page-navigation">${parent?`<a class="btn back-link" id="page-back" href="#${parent}"><span aria-hidden="true">← </span>${backLabel}</a>`:''}<nav class="breadcrumb" aria-label="面包屑"><ol>${ancestors.map(id=>`<li><a href="#${id}">${routeLabels[id]}</a></li>`).join('')}<li aria-current="page">${esc(name)}</li></ol></nav></div>`;
}
const title=(name,desc,action='')=>`${pageNavigation(name)}<div class="heading"><div><h1>${name}</h1><p>${desc}</p></div><div class="actions">${action.replace(/<a\b[^>]*>返回[^<]*<\/a>/g,'')}</div></div>`;
const panel=(name,body)=>`<section class="panel"><h2>${name}</h2>${body}</section>`;
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3800);}
function summary(){return (state.role==='visitor'||(state.phase==='1'&&state.role==='creator'))?emptyOverview():`${title('今天，从这里继续','查看需要处理的事，或接着完成上次的创作。',link('继续编辑月影旅馆','editor','primary'))}<div class="columns"><div><section class="panel bar"><div class="panel-bar">需要你处理 <span>2 项</span></div><div class="panel-inner"><div class="todo"><i class="dot"></i><div><h3>旧港口夜行需要补充集合说明</h3><p>世界管理员退回了这个版本 · 今天 10:24</p></div>${link('查看意见','returned')}</div><div class="todo"><i class="dot green"></i><div><h3>伊莎贝拉收到一条新的评价</h3><p>月影旅馆 ·「夜里的渡船很安静」</p></div>${link('去回复','interactions?tab=received')}</div></div></section>${panel('继续创作',`<div class="todo"><div><h3>月影旅馆 · 临港房间</h3><p>住宿 · 伊莎贝拉 · 拉斯世界</p>${badge('已公开','green')} ${badge('草稿 v3 未提交')}</div>${link('继续编辑','editor')}</div><div class="todo"><div><h3>阿莱克斯的角色简介</h3><p>草稿已保存，尚未提交</p></div>${link('编辑资料','persona')}</div>`)}</div><div>${panel('快捷开始',`<div class="shortcuts">${link('＋ 创建角色','persona')}${link('＋ 创建作品','new-work')}${state.phase==='2'?link('浏览可申请的世界','admissions'):''}</div>`)}${state.phase==='2'?panel('最近的进展',`<p>${badge('已通过','green')}</p><h3>拉斯世界的入驻申请已通过</h3><p class="muted">可以在这里创作住宿、活动和服务。</p><small>概览展示可行动的状态，不用数据图表占据首页。</small>`):panel('最近的进展','<p>阿莱克斯的角色资料已保存，尚未提交审核。</p>')}</div></div>`;}
function emptyOverview(){return `${title('从一个角色开始','你可以用自己的角色记录旅行，也可以逐步建立自己的作品。')}<div class="card-grid">${panel('01 创建一个角色',`<p>为故事中的你取一个名字。</p>${link('创建角色','persona','primary')}`)}${state.phase==='2'?panel('02 入驻一个世界',`<p>获得创作资格后，经营房子、活动或服务。</p>${link('查看入驻','admissions')}`)+panel('03 创建自己的世界',`<p>准备设定，提交网站审核。</p>${link('创建世界','world-new')}`):''}</div>`;}
function workList(){if(state.role==='visitor'||(state.phase==='1'&&state.role==='creator'))return `${title('我的作品','入驻世界后，你的住宿、活动和服务会出现在这里。')}<div class="panel empty"><h2>还没有作品</h2><p>你仍然可以创建角色、发表游客评价。</p>${state.phase==='2'?link('申请入驻','admissions','primary'):link('管理角色','personas')}</div>`;
 const filtered=works.filter(w=>(state.kind==='all'||w.kind===state.kind)&&(state.status==='all'||w.status===state.status)&&w.name.includes(state.search));
 return `${title('我的作品','同一个地方管理所有角色的作品。',link('＋ 创建作品','new-work','primary'))}<div class="filters"><input id="search" aria-label="搜索作品" placeholder="搜索作品名称" value="${esc(state.search)}"><select id="kind" aria-label="作品类型"><option value="all">全部类型</option><option value="stay">住宿</option><option value="experience">活动</option><option value="service">服务</option></select><select id="status" aria-label="作品状态"><option value="all">全部状态</option><option value="published">已公开</option><option value="draft">草稿</option><option value="rejected">已退回</option></select><button data-action="filter">筛选</button></div><p class="muted">${filtered.length} 件作品 · 拉斯世界 · 全部角色</p><div class="card-grid">${filtered.map(w=>`<article class="work-card"><div class="work-art ${w.kind}">${w.icon}</div><div class="work-body"><p class="eyebrow">${w.label} / 拉斯世界</p><h3>${w.name}</h3><p>经营者：${w.persona}</p>${badge(w.state,w.color)}${link(w.status==='rejected'?'查看意见并修改':'编辑作品',w.status==='rejected'?'returned':'editor')}</div></article>`).join('')||'<p>没有匹配的作品。试着调整筛选。</p>'}</div>`;}
function personas(){return `${title('我的角色','角色属于你的账号，可以在不同世界担任不同身份。',link('＋ 创建角色','persona','primary'))}<div class="card-grid">${['伊莎贝拉','阿莱克斯'].map((name,i)=>`<article class="panel"><div class="person-head"><div class="avatar">${i?'阿':'伊'}</div><div><h3>${name}</h3>${badge(i?'草稿未提交':'资料已批准',i?'':'green')}</div></div><p>${i?'记录每一次离开与抵达的旅人。':'在旧港口经营旅馆，也为过路的旅人修理装备。'}</p><p class="muted">${i?'1 篇游客评价':'2 件作品 · 3 篇游客评价'}</p>${link('编辑资料','persona')}</article>`).join('')}</div><p class="muted">角色公开主页留待后续；改名不会自动改变旧评价的署名。</p>`;}
function persona(){return `${title('编辑角色','保存资料草稿后，可以继续创作评价；提交与保存是两个动作。',link('返回我的角色','personas'))}<div class="columns">${panel('角色资料',`<div class="person-head"><div class="avatar">阿</div><div><h3>阿莱克斯</h3>${badge('未提交')}</div></div><div class="tabs"><button aria-selected="true">中文</button><button data-action="hint" data-message="正式版本在同一资料版本中维护中英文；此处为中文字段草图。">English</button></div><label class="field">角色名字<input value="阿莱克斯"></label><label class="field">简短介绍<textarea>记录每一次离开与抵达的旅人。</textarea></label><label class="field">内置头像<select><option>薄荷绿</option><option>琥珀</option><option>紫罗兰</option><option>天空蓝</option></select></label><div class="actions"><button data-action="hint" data-message="草图演示：资料草稿已保存，没有提交审核。">保存草稿</button><button class="primary" data-action="hint" data-message="草图演示：将当前资料版本提交网站管理员。正式实现依赖 BUG-001。">提交资料审核</button></div>`)}${panel('发布与审核',`<div class="note warning">这一版尚未提交。保存不等于送审。</div><p>资料由网站管理员审核；世界管理员审核世界内的作品和发言。</p><h3>当前公开资料</h3><p class="muted">暂无。草稿只有你和获授权的审核者可见。</p>`)}</div>`;}
const sections=[['basics','名称与简介'],['gallery','图片'],['description','详细介绍'],['amenities','设施'],['price','价格与规格'],['provider','经营角色'],['rules','入住须知']];
function fieldBody(){const d=draft[state.language];switch(state.section){case 'basics':return `<label class="field">${state.language==='zh'?'作品名称':'Title'}<input id="edit-title" value="${esc(d.title)}"></label><div class="note">名称会用于既有详情页和作品卡片。</div>`;case 'description':return `<label class="field">${state.language==='zh'?'详细介绍':'Description'}<textarea id="edit-description">${esc(d.description)}</textarea></label><p class="muted">公开页继续采用现有的介绍栏目。</p>`;case 'price':return `<label class="field">每间每晚的虚构价格<input id="edit-price" type="number" min="0" value="${draft.price}"></label><p>单位：铸币 / 每间每晚</p><div class="note">金额双语共用，不填写真实支付信息。</div>`;case 'gallery':return `<div class="image-slot">现有图片缩略图与排序区域</div><label class="field">图片地址<input placeholder="https://… 或 /media/…"></label><label class="field">图片说明<textarea>窗边的书桌与远处的港口。</textarea></label><small>首版沿用现有图片引用能力；文件上传服务另行评估。</small>`;case 'amenities':return `<div class="note">项目与顺序中英共用，文字分别填写。</div><label class="field">设施 1<input value="阅读灯"></label><label class="field">设施 2<input value="安静的书桌"></label><button data-action="hint" data-message="正式实现复用 BUG-002 的共用项目增删排序规则。">＋ 添加设施</button>`;case 'provider':return `<div class="person-head"><div class="avatar">伊</div><div><h3>伊莎贝拉</h3>${badge('已绑定经营者','green')}</div></div><p>角色姓名和简介来自已批准资料。</p>${link('管理我的角色','personas')}<div class="note">编辑作品与替换经营角色分别校验权限。绑定操作留在获授权的管理流程。</div>`;default:return `<label class="field">入住须知<textarea>请在午夜钟声后保持安静。离开时将地图放回书桌。</textarea></label><small>本区是布局占位；完整字段见工程交接清单。</small>`;}}
function editor(){if(state.role==='visitor'||(state.phase==='1'&&state.role==='creator'))return `${title('作品编辑','当前示例账号尚未取得本作品编辑权限。')}${link('返回工作台','overview')}`;
 return `${title('编辑月影旅馆','拉斯世界 / 住宿 · 经营者：伊莎贝拉',link('返回作品列表','works'))}<div class="actions role-note">${badge('公开版本 v2','green')} ${badge(state.submitted?'草稿 v'+state.revision+' 待审核':'草稿 v'+state.revision)}<span>游客继续看到公开版本，保存不会发布。</span></div><nav class="section-list" aria-label="编辑栏目">${sections.map(([id,label])=>`<button data-section="${id}" aria-pressed="${id===state.section}">${label}</button>`).join('')}</nav><div class="editor-toolbar"><div class="actions"><button data-lang="zh" ${state.language==='zh'?'class="primary"':''}>中文</button><button data-lang="en" ${state.language==='en'?'class="primary"':''}>English</button></div><div class="mobile-mode actions"><button data-mode="edit">编辑</button><button data-mode="preview">预览</button></div><label>预览宽度 <select id="width"><option value="desktop">桌面</option><option value="phone">手机</option></select></label></div><div class="editor-grid" data-mode="${state.mode}"><section class="panel fields-panel"><h2>${sections.find(x=>x[0]===state.section)[1]}</h2><div id="fields">${fieldBody()}</div></section><section class="panel preview-panel"><div class="actions"><h2>已保存版本的预览</h2>${badge('结构占位示意')}</div><p class="screen-note">此草图仅表达编辑交互。正式版本原样复用现有前台详情。</p><div class="preview-wrap ${state.width==='phone'?'phone':''}"><iframe id="preview" title="作品草稿预览"></iframe></div></section></div><div class="save-bar"><span id="save-state" class="save-state"></span><div class="actions"><button data-action="save">保存草稿</button><button data-action="save-preview">保存并预览</button><button class="primary" data-action="submit">${state.role==='creator'?'提交审核':'确认发布'}</button></div></div><details class="screen-note"><summary>设计验证用状态（正式界面不显示）</summary><label>模拟下一次保存结果<select id="failure"><option value="none">成功</option><option value="conflict">版本冲突</option><option value="session">会话过期</option><option value="network">网络失败</option></select></label></details>`;}
function previewDocument(){const s=saved[state.language],session='demo-session',revision=String(state.revision);return `<!doctype html><html lang="zh-CN"><meta charset="utf-8"><style>body{font:14px/1.6 system-ui;margin:0;padding:24px;background:#fffef9;color:#31382d}h1{font-size:24px}h2{font-size:17px}section{padding:15px 0;border-bottom:1px solid #d9dfd0;cursor:pointer}section:focus{outline:2px solid #83a139}small{color:#687260}.image{height:120px;background:#dce5ce;display:grid;place-items:center;color:#627552}p{white-space:pre-wrap}.selected{outline:2px solid #83a139;outline-offset:4px}</style><small>示意画布 · 保存版本 ${revision} · 不代表前台改版</small><section data-section="basics" tabindex="0"><h1>${esc(s.title)}</h1><small>拉斯世界 · 伊莎贝拉经营</small></section><section data-section="gallery" tabindex="0"><div class="image">现有图库位置</div></section><section data-section="description" tabindex="0"><h2>关于这个房间</h2><p>${esc(s.description)}</p></section><section data-section="amenities" tabindex="0"><h2>设施</h2>阅读灯 · 安静的书桌</section><section data-section="price" tabindex="0"><strong>${saved.price} 铸币 / 每间每晚</strong></section><section data-section="provider" tabindex="0"><h2>经营者：伊莎贝拉</h2></section><section data-section="rules" tabindex="0"><h2>入住须知</h2></section><script>const session=${JSON.stringify(session)},revision=${JSON.stringify(revision)},origin=location.origin==='null'?parent.location.origin:location.origin;const send=e=>{const t=e.target.closest('[data-section]');if(t)parent.postMessage({channel:'plotstay-preview-v1',type:'select',session,revision,section:t.dataset.section},origin)};document.addEventListener('click',send);document.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' ')send(e)});window.addEventListener('message',e=>{const d=e.data;if(e.origin!==origin||e.source!==parent||d?.channel!=='plotstay-preview-v1'||d.session!==session||d.revision!==revision||d.type!=='focus')return;const target=[...document.querySelectorAll('[data-section]')].find(x=>x.dataset.section===d.section);if(!target)return;document.querySelectorAll('.selected').forEach(x=>x.classList.remove('selected'));target.classList.add('selected');target.scrollIntoView({block:'center'});});<\/script></html>`;}
function mountPreview(){bridge?.destroy();const frame=$('#preview');if(!frame)return;frame.srcdoc=previewDocument();bridge=createPreviewBridge({frame,origin:location.origin,session:'demo-session',revision:String(state.revision),onSelect:section=>{state.section=section;$('#fields').innerHTML=fieldBody();$('.fields-panel h2').textContent=sections.find(x=>x[0]===section)[1];document.querySelectorAll('[data-section]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.section===section)));state.mode='edit';$('.editor-grid').dataset.mode='edit';$('#fields input, #fields textarea')?.focus();bridge.select(section);}});frame.addEventListener('load',()=>bridge.select(state.section),{once:true});updateSave();}
function updateSave(){if($('#save-state'))$('#save-state').textContent=state.dirty?`有未保存修改 · 预览仍为 v${state.revision}`:`已保存 v${state.revision} · 公开版本 v2`;}
function save(){if(state.fail!=='none'){const messages={conflict:'另一位编辑已更新内容。你的输入已保留，请比较最新版本后再保存。',session:'会话已过期。输入已保留，重新登录后重试。',network:'保存失败。输入与旧预览均已保留，请重试。'};toast(messages[state.fail]);return false;}if(state.dirty){saved=structuredClone(draft);state.revision++;state.dirty=false;}mountPreview();toast('草图演示：草稿已保存，公开版本保持 v2。');return true;}
function interactions(){const received=state.tab==='received';return `${title('评价与回复','按任务找到自己的发言，或处理作品收到的评价。')}<div class="tabs"><button data-tab="mine" aria-selected="${!received}">我写的评价</button><button data-tab="received" aria-selected="${received}">作品收到的评价</button></div><div class="columns">${panel(received?'夜里的渡船很安静':'第一次沿着旧港口散步',`<div class="actions">${badge('已公开','green')}<small>${received?'游客：阿莱克斯':'署名：阿莱克斯'} · 月影旅馆</small></div><div class="review-body">${received?'窗边的灯一直亮着，房东留下的地图帮了很大的忙。下次想在这里多住几晚。':'旅途中最喜欢的时刻，是在窗边看见午夜的渡船。'}</div>${received?`<div class="note">以绑定的经营者「伊莎贝拉」回复，不能任意切换署名。</div><label class="field">提供者回复<textarea id="reply">谢谢你记得那盏灯。下次抵达时，地图还会在那里。</textarea></label><div class="actions"><button data-action="hint" data-message="草图演示：回复草稿已保存。">保存回复草稿</button><button class="primary" data-action="hint" data-message="草图演示：提供者回复按现有流程送审。">提交回复审核</button></div>`:`<div class="review-reply"><strong>伊莎贝拉回复</strong><p>谢谢你留下旅途中的这一页。</p></div><button data-action="hint" data-message="正式版打开本人评价编辑器，保留既有署名和评分规则。">修改我的评价</button>`}`)}${panel('本次互动范围',`<p>保留现有“一篇评价＋一条提供者回复”。</p><p class="muted">来回多轮回复预留接口，不在本轮添加前台对话界面。</p>`)}</div>`;}
function admissions(){return `${title('入驻与申请','入驻资格属于你的账号，通过后可以使用自己的不同角色创作。')}<div class="columns"><div>${panel('已入驻',`<div class="queue-item"><div><h3>拉斯世界</h3><p class="muted">住宿、活动、服务均可创作 · 账号资格</p>${badge('已入驻','green')}</div>${link('创建作品','new-work','primary')}</div>`)}${panel('申请进度',`<h3>雾谷</h3>${badge('待审核','orange')}<p>管理员正在查看你的创作方向。</p><small>草图提案：待审期间不开放该世界的作品新建，详见待确认清单。</small>`)}</div>${panel('可申请的世界',`<h3>旧城群岛</h3><p>开放申请 · 欢迎创作港口生活与旅行故事。</p><label class="field">你想创作什么？<textarea placeholder="介绍计划经营的住宿、活动或服务，以及想使用的角色。"></textarea></label><button class="primary" data-action="hint" data-message="草图演示：入驻申请已提交，等待世界管理员审核。">提交入驻申请</button><hr><h3>纸月档案馆</h3><p class="muted">仅限邀请。收到邀请后在这里接受。</p>`)}</div>`;}
function worlds(){return `${title('我管理的世界','这里展示管理权限；经营资格请到“入驻与申请”查看。',state.phase==='2'?link('＋ 创建世界','world-new','primary'):'')}<div class="card-grid">${panel('拉斯世界',`${badge('已公开','green')}<p>你的权限：世界所有者</p><div class="stats"><div><strong>${state.phase==='2'?'2':'0'}</strong><small>${state.phase==='2'?'入驻待审':'资料待处理'}</small></div><div><strong>3</strong><small>作品待审</small></div></div>${link('进入世界管理','world','primary')}`)}${state.phase==='2'?panel('星灯群岛',`${badge('世界草稿')}<p>尚未提交网站审核，内部内容不会公开。</p>${link('继续准备世界','world-new')}`):''}</div>`;}
function world(){return `${title('拉斯世界管理','世界所有者 · 审核与维护仅作用于这个世界。',link('返回个人工作台','worlds'))}<div class="tabs">${link('审核队列','world')}${link('世界内容','world-content')}${link('世界设定','world-settings')}${link('成员与权限','world-members')}</div>${panel('待处理',`<div class="queue-item"><div>${badge('作品修改','orange')}<h3>月影旅馆 · 临港房间</h3><small>申请者：林 · 经营者：伊莎贝拉 · 修改 2 个栏目</small></div>${link('查看修改','review','primary')}</div>${state.phase==='2'?`<div class="queue-item"><div>${badge('入驻申请')}<h3>迟来的旅人</h3><small>希望创作灯塔附近的住宿与步行活动</small></div>${link('查看申请','admission-review')}</div>`:''}`)}<div class="note">跨世界 persona 资料由网站管理员审核；此处不授予角色资料审批权。</div>`;}
function review(){return `${title('审核作品修改','月影旅馆 · 临港房间 / 待审 v3 · 审核的是这个固定版本',link('返回审核队列','world'))}<div class="review-columns">${panel('当前公开 v2',`<h3>月影旅馆</h3><p>窗边能看见港口。</p><div class="original">此处为差异草图，正式版以不可变版本生成。</div>`)}${panel('本次送审 v3',`<h3>月影旅馆 · 临港房间</h3><p>窗边能看见午夜靠港的渡船。书桌上留着一份手绘地图。</p>${badge('名称已修改')} ${badge('介绍已修改')}`)}</div>${panel('审核决定',`<label class="field">给创作者的说明<textarea id="review-note" placeholder="退回时说明需要修改的具体问题。"></textarea></label><div class="actions"><button data-action="review-reject">退回修改</button><button class="primary" data-action="hint" data-message="草图演示：批准固定送审版本；服务端仍需核对申请是否过期。">批准并发布</button></div>`)}<div class="note">正式审核还需提供受保护的完整页面预览。世界未公开或网站限制未解除时，不能发布作品。</div>`;}
function returned(){return `${title('这件作品需要修改','旧港口夜行 · 活动 · 待修改版本 v2',link('返回作品列表','works'))}${panel('世界管理员的意见',`<div class="note warning">请补充集合地点的准确描述，以及迟到后的安排。</div><p>退回只影响这次送审版本；已有公开版本继续展示。</p>${link('进入作品编辑','editor','primary')}<p class="screen-note">草图编辑器以住宿为演示；活动的专有栏目见页面规格。</p>`)}`;}
function worldNew(){return `${title('创建世界草稿','先保存设定，再提交网站管理员审核。审核通过前，世界与内部作品不会公开。',link('返回我的世界','worlds'))}<div class="columns">${panel('基本设定',`<label class="field">世界名称<input value="星灯群岛"></label><label class="field">世界介绍<textarea>沿着灯塔航线连接起来的群岛。每一座岛都有自己的午夜。</textarea></label><label class="field">入驻方式<select><option>开放申请，经管理员批准</option><option>仅限邀请</option></select></label><label class="field">创作规则<textarea>欢迎创作岛屿之间的旅行、住宿与日常生活。</textarea></label><div class="actions"><button data-action="hint" data-message="草图演示：世界草稿已保存，你是世界所有者。">保存世界草稿</button><button class="primary" data-action="hint" data-message="草图演示：提交固定世界版本，等待网站管理员审核。">提交世界审核</button></div>`)}${panel('准备进度',`<p>✓ 创建者：当前账号</p><p>✓ 入驻规则已选择</p><p>○ 中英世界资料待检查</p><div class="note">世界草稿期间可以准备内容；公开发布需要世界审核通过。</div>`)}</div>`;}
function newWork(){return `${title('创建作品','先确定世界、作品类型和故事里的经营者。',link('返回我的作品','works'))}${panel('作品归属',`<div class="form-grid"><label>创作世界<select><option>拉斯世界 · ${state.role==='creator'?'已入驻':'可管理'}</option></select></label><label>类型<select id="new-kind"><option>住宿</option><option>活动</option><option>服务</option></select></label><label class="wide">经营角色<select><option>伊莎贝拉 · 资料已批准</option><option>阿莱克斯 · 草稿（完整流程待定）</option></select></label></div><div class="note">世界和编辑资格由账号决定；角色决定对外显示的经营身份。</div>${link('继续填写作品','editor','primary')}<p class="screen-note">此交互草图统一进入住宿示例；活动与服务沿用相同框架、使用各自栏目。</p>`)}`;}
function misc(){if(route==='admission-review')return `${title('审核入驻申请','拉斯世界 / 申请者：迟来的旅人',link('返回世界管理','world'))}${panel('创作方向',`<p>计划以灯塔看守人的身份经营海边小屋，并提供夜间步行活动。</p><div class="note">通过后，授予账号本世界的三类作品创作资格，不授予管理权。</div><label class="field">审核说明<textarea></textarea></label><div class="actions"><button data-action="hint" data-message="草图演示：申请被退回，保留审核说明。">拒绝申请</button><button class="primary" data-action="hint" data-message="草图演示：账号获得本世界创作资格。">批准入驻</button></div>`)}`;
 if(route==='world-content')return `${title('世界内容','管理范围：拉斯世界。这里可以看到被授权管理的全部作品。',link('返回世界管理','world'))}${panel('内容列表',works.map(w=>`<div class="queue-item"><div><h3>${w.name}</h3><small>${w.label} · 经营者 ${w.persona}</small> ${badge(w.state)}</div>${link('编辑作品','editor')}</div>`).join(''))}${panel('原有管理工具',`<div class="actions">${['批量导入','翻译任务','共享资料','发布历史'].map(x=>`<button data-action="hint" data-message="${x}必须保留原有操作，迁移清单见交接文档。">${x}</button>`).join('')}</div>`)}`;
 if(route==='world-settings'&&state.phase==='1')return `${title('世界设定','保留现有世界首页、地点及共享资料的维护能力。',link('返回世界管理','world'))}${panel('已有设置入口','<p>世界首页配置 · 地点资料 · 共享人物资料 · 文案与翻译</p><p class="muted">完整字段与原操作见迁移清单；本草图仅展示入口组织。</p>')}`;
 if(route==='world-settings')return `${title('世界设定','本次调整后台表单组织，现有前台呈现保持不变。',link('返回世界管理','world'))}${panel('拉斯世界',`<label class="field">入驻方式<select><option>开放申请</option><option>仅限邀请</option></select></label><label class="field">创作说明<textarea>欢迎创作与世界设定一致的住宿、活动与服务。</textarea></label><button data-action="hint" data-message="世界资料公开后的修改审核范围仍为待确认事项；此草图不模拟直接发布。">保存设定草稿</button>`)}`;
 if(route==='world-members')return `${title('成员与创作者','管理成员与入驻资格分别列出。',link('返回世界管理','world'))}${panel('世界管理成员','<p>林 · 所有者</p><p class="muted">变更管理角色需单独授权，不随入驻申请授予。</p>')}${state.phase==='2'?panel('入驻创作者',`<div class="queue-item"><div><h3>迟来的旅人</h3>${badge('已入驻','green')}</div><button class="danger" data-action="hint" data-message="正式版需确认：暂停新增、修改提交与提供者回复，保留已有作品；下架另行操作。">取消入驻资格</button></div>`):''}`;
 if(route==='site'&&state.phase==='1')return `${title('网站审核','角色资料审核与账号管理。')}${panel('角色资料待审','<p>阿莱克斯 · 当前送审资料 v2</p><p class="muted">独立角色审核依赖 BUG-001；账号创建及原审核能力继续保留。</p>')}`;
 if(route==='site')return `${title('网站审核','处理世界首次公开与跨世界的 persona 资料。')}<div class="tabs"><button>世界申请</button><button data-action="hint" data-message="角色资料队列复用 BUG-001 的独立审核入口。">角色资料</button><button data-action="hint" data-message="保留现有管理员创建普通账号的功能。">账号管理</button></div>${panel('星灯群岛申请公开',`<p>创建者：林 · 世界资料 v1 · 入驻方式：开放申请</p><label class="field">审核说明<textarea></textarea></label><div class="actions"><button data-action="hint" data-message="草图演示：退回世界申请。">退回</button><button class="primary" data-action="hint" data-message="草图演示：世界获准公开；不自动发布尚未审核的作品。">批准世界公开</button></div>`)}`;
 return `${title('账号设置','账号资料与故事里的角色资料分别管理。')}${panel('当前账号',`<div class="detail-row"><span>登录邮箱</span><span>creator@example.test</span></div><div class="detail-row"><span>角色资料</span><span>${link('前往我的角色','personas')}</span></div><p class="muted">首批沿用已有登录与退出能力；改密等新能力不放无效入口。</p><button data-action="hint" data-message="草图演示：退出账号。正式版调用现有 logout 接口。">退出登录</button>`)}`;}
function render(){bridge?.destroy();const full=state.phase==='2',role=state.role;
 $('#nav').innerHTML=nav.filter(([id])=>(full||!['admissions'].includes(id))&&(full||role!=='creator'||id!=='works')&&(!(role==='visitor'||role==='creator')||id!=='worlds')&&(role!=='visitor'||id!=='works'||full)).map(([id,label,icon])=>`<a href="#${id}" ${route===id?'aria-current="page"':''}><span class="nav-icon">${icon}</span>${label}</a>`).join('')+(role==='site'?'<a href="#site">网站审核</a>':'');
 if(!full&&['admissions','world-new','admission-review'].includes(route)){route='overview';history.replaceState(null,'','#overview');}
 const ownerRoutes=['worlds','review','world','world-content','world-settings','world-members','admission-review'];
 if(ownerRoutes.includes(route)&&!['owner','site'].includes(role))$('#main').innerHTML=title('当前没有世界管理权限','你可以在“入驻与申请”管理自己的经营资格。',link('回到概览','overview'));
 else if(route==='site'&&role!=='site')$('#main').innerHTML=title('需要网站管理权限','世界管理权限不能替代网站审核权限。',link('回到概览','overview'));
 else $('#main').innerHTML=({overview:summary,works:workList,personas,persona,editor,interactions,admissions,worlds,world,review,returned,'world-new':worldNew,'new-work':newWork}[route]??misc)();
 if($('#kind'))$('#kind').value=state.kind;if($('#status'))$('#status').value=state.status;if($('#width'))$('#width').value=state.width;if($('#failure'))$('#failure').value=state.fail;mountPreview();
}
function navigate(){const parts=location.hash.slice(1).split('?');const next=parts[0]||'overview';if(route==='editor'&&state.dirty&&next!==route&&!confirm('有未保存修改。离开并放弃这些修改？')){history.replaceState(null,'','#editor');return;}if(next!==route&&state.dirty){draft=structuredClone(saved);state.dirty=false;}if(next==='editor'&&route!=='editor')editorContext=route==='world-content'?'world-content':'works';route=next;if(parts[1])state.tab=new URLSearchParams(parts[1]).get('tab')||'mine';render();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.section){state.section=b.dataset.section;$('#fields').innerHTML=fieldBody();$('.fields-panel h2').textContent=sections.find(x=>x[0]===state.section)[1];document.querySelectorAll('[data-section]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));bridge?.select(state.section);}
 if(b.dataset.lang){state.language=b.dataset.lang;render();}if(b.dataset.mode){state.mode=b.dataset.mode;$('.editor-grid').dataset.mode=state.mode;}if(b.dataset.tab){state.tab=b.dataset.tab;render();}
 const a=b.dataset.action;if(a==='hint')toast(b.dataset.message);if(a==='filter'){state.search=$('#search').value;state.kind=$('#kind').value;state.status=$('#status').value;render();}if(a==='save'||a==='save-preview'){if(save()&&a==='save-preview'){state.mode='preview';$('.editor-grid').dataset.mode='preview';}}
 if(a==='submit'){if(state.dirty){toast('请先保存并预览当前修改，再提交或发布。');return;}if(confirm(state.role==='creator'?'将当前保存版本提交世界管理员审核？':'确认发布当前保存版本？此处仅模拟，不改变网站。')){state.submitted=true;render();toast(state.role==='creator'?'草图演示：当前版本已提交审核。':'草图演示：发布动作已确认。实际网站没有变化。');}}
 if(a==='review-reject'){const note=$('#review-note');if(!note.value.trim()){note.focus();toast('请填写具体的退回原因。');}else toast('草图演示：当前申请已退回，创作者会看到这条说明。');}
});
document.addEventListener('input',e=>{if(e.target.id==='edit-title')draft[state.language].title=e.target.value;else if(e.target.id==='edit-description')draft[state.language].description=e.target.value;else if(e.target.id==='edit-price')draft.price=Number(e.target.value);else return;state.dirty=true;state.submitted=false;updateSave();});
document.addEventListener('change',e=>{if(e.target.id==='phase'){state.phase=e.target.value;render();}if(e.target.id==='role'){state.role=e.target.value;render();}if(e.target.id==='width'){state.width=e.target.value;$('.preview-wrap').classList.toggle('phone',state.width==='phone');}if(e.target.id==='failure')state.fail=e.target.value;});
window.addEventListener('hashchange',navigate);navigate();
